{"content": "# ============================================================================
# MODULAR AUXILIARY FUNCTIONS
# ============================================================================

#' Build initial state from abscissae and log-density values
#'
#' @param x sorted abscissae
#' @param lx log-density values at x
#' @param domain length-2 numeric vector [lower, upper]
#' @return list with state components
.build_state <- function(x, lx, domain) {
  list(
    x = x,
    lx = lx,
    domain = domain,
    # Slopes between consecutive points
    slopes = diff(lx) / diff(x),
    # Upper envelope: tangent lines at each interior point
    upper_a = numeric(length(x)),
    upper_b = numeric(length(x)),
    # Lower envelope: secant lines on each interval
    lower_a = numeric(length(x) - 1),
    lower_b = numeric(length(x) - 1),
    lower_w = diff(x)   # interval widths
  )
}

#' Rebuild the upper and lower envelopes from a set of abscissae
#'
#' @param x sorted abscissae
#' @param lx log-density values at x
#' @param domain length-2 numeric vector
#' @return state list
.rebuild_envelope <- function(x, lx, domain) {
  n <- length(x)
  state <- .build_state(x, lx, domain)

  # Slopes
  s <- diff(lx) / diff(x)

  # Lower envelope (secants): linear on each interval
  for (j in seq_len(n - 1)) {
    state$lower_a[j] <- lx[j] - s[j] * x[j]
    state$lower_b[j] <- s[j]
  }

  # Upper envelope (tangents):
  # For interior points, tangent slope = interpolated slope between adjacent secants
  # For endpoints, slope = adjacent secant slope
  for (j in seq_len(n)) {
    if (j == 1) {
      m <- s[1]
    } else if (j == n) {
      m <- s[n - 1]
    } else {
      m <- (s[j - 1] + s[j]) / 2
    }
    state$upper_a[j] <- lx[j] - m * x[j]
    state$upper_b[j] <- m
  }

  state
}

#' Evaluate the lower envelope at a point
#'
#' @param u scalar
#' @param state state list from .rebuild_envelope
#' @return lower envelope value
.lower_envelope_at <- function(u, state) {
  x <- state$x
  n <- length(x)
  if (u <= x[1]) return(-Inf)
  if (u >= x[n]) return(-Inf)

  # Find interval
  j <- findInterval(u, x)
  if (j < 1 || j >= n) return(-Inf)

  state$lower_a[j] + state$lower_b[j] * u
}

#' Sample a candidate from under the lower envelope
#'
#' Uses the distribution function of the lower envelope (piecewise linear).
#'
#' @param state state list
#' @param domain length-2 numeric vector
#' @return scalar candidate
.sample_from_lower <- function(state, domain) {
  x <- state$x
  n <- length(x)
  la <- state$lower_a
  lb <- state$lower_b
  w <- state$lower_w

  # Cumulative area under each trapezoid
  areas <- numeric(n - 1)
  for (j in seq_len(n - 1)) {
    h1 <- la[j] + lb[j] * x[j]
    h2 <- la[j] + lb[j] * x[j + 1]
    areas[j] <- 0.5 * (h1 + h2) * w[j]
  }

  total_area <- sum(areas)
  if (total_area <= 0) {
    # Fallback: sample uniformly in domain
    return(runif(1, domain[1], domain[2]))
  }

  u <- runif(1) * total_area
  cum_area <- 0

  for (j in seq_len(n - 1)) {
    cum_area <- cum_area + areas[j]
    if (u <= cum_area) {
      # Sample from trapezoid j
      target <- u - (cum_area - areas[j])
      h1 <- la[j] + lb[j] * x[j]
      h2 <- la[j] + lb[j] * x[j + 1]
      candidate <- .sample_trapezoid(target, h1, h2, x[j], x[j + 1])
      return(candidate)
    }
  }

  # Fallback (should rarely happen)
  return(runif(1, domain[1], domain[2]))
}

#' Sample from a trapezoid with heights h1, h2 on [a, b]
#'
#' @param target cumulative target within [0, area]
#' @param h1 height at left endpoint
#' @param h2 height at right endpoint
#' @param a left endpoint
#' @param b right endpoint
#' @return scalar sample
.sample_trapezoid <- function(target, h1, h2, a, b) {
  area <- 0.5 * (h1 + h2) * (b - a)
  if (area <= 0) return((a + b) / 2)

  u <- runif(1) * area
  mid <- h1 * (b - a)

  if (u <= mid) {
    # Left triangle (or rectangle if h1 == h2)
    if (h1 > 0) {
      return(a + sqrt(2 * u * (b - a) / h1))
    } else {
      return(a + u / (0.5 * h2 * (b - a)) * (b - a))
    }
  } else {
    # Right triangle (or trapezoid remainder)
    rem <- u - mid
    if (h2 > 0) {
      return(b - sqrt(2 * (area - rem) * (b - a) / h2))
    } else {
      return(a + rem / (0.5 * h1 * (b - a)) * (b - a))
    }
  }
}

#' Check log-concavity after adding a new point
#'
#' Ensures the second differences remain non-positive.
#'
#' @param pool_x sorted abscissae
#' @param pool_lx log-density values
#' @param new_x new abscissa
#' @param new_lx log-density at new abscissa
#' @return logical
.check_log_concavity <- function(pool_x, pool_lx, new_x, new_lx) {
  new_pool_x <- c(pool_x, new_x)
  new_pool_lx <- c(pool_lx, new_lx)
  idx <- order(new_pool_x)
  new_pool_x <- new_pool_x[idx]
  new_pool_lx <- new_pool_lx[idx]

  second_diffs <- .compute_second_differences(new_pool_x, new_pool_lx)
  all(second_diffs <= 0)
}

#' Compute second differences of log-density values
#'
#' @param x sorted abscissae
#' @param lx log-density values
#' @return numeric vector of second differences
.compute_second_differences <- function(x, lx) {
  if (length(x) < 3) return(numeric(0))
  dx1 <- diff(x)
  dx2 <- diff(x[-1])
  slopes <- diff(lx) / c(dx1, dx2)
  diff(slopes) / 0.5 * (dx1[-length(dx1)] + dx2[-length(dx2)])
}

#' Print method for ars_result objects
#'
#' @param x ars_result object
#' @param ... additional arguments
.print_ars_result <- function(x, ...) {
  cat("Adaptive Rejection Sampling Result\n")
  cat("===================================\n")
  cat(sprintf("Number of samples: %d\n", length(x$samples)))
  cat(sprintf("Mean: %.6f\n", mean(x$samples)))
  cat(sprintf("SD:   %.6f\n", sd(x$samples)))
  cat(sprintf("Evaluation points used: %d\n", length(x$evaluation_points)))
  cat("\nFirst 10 samples:\n")
  print(head(x$samples, 10))
}
