{"content": "# ============================================================================
# Adaptive Rejection Sampling (ARS)
# Based on Gilks & Wild (1992)
# "Adaptive rejection sampling for Gibbs sampling."
# Journal of the Royal Statistical Society: Series C (Applied Statistics), 41(2), 337-348.
# ============================================================================

# ============================================================================
# MAIN FUNCTION
# ============================================================================

ars <- function(
  logdensity,
  n,
  domain = c(-Inf, Inf),
  init_points = NULL,
  max_iter = 1000,
  force_max_iter = TRUE,
  verbose = FALSE
) {
  # -------------------------------------------------------------------------
  # Input validation
  # -------------------------------------------------------------------------
  if (!is.function(logdensity)) {
    stop("The 'logdensity' argument must be a function that evaluates the log-density.")
  }

  if (!is.numeric(n) || length(n) != 1 || n < 1 || floor(n) != n) {
    stop("The 'n' argument must be a positive integer.")
  }

  if (!is.numeric(domain) || length(domain) != 2) {
    stop("The 'domain' argument must be a numeric vector of length 2.")
  }
  if (is.infinite(domain[1]) || is.infinite(domain[2]) || domain[1] >= domain[2]) {
    stop("The 'domain' argument must specify a finite interval with lower < upper.")
  }

  # Evaluate logdensity at domain boundaries to check for Inf/NaN
  lb_val <- tryCatch(logdensity(domain[1]), error = function(e) NA, warning = function(w) NA)
  ub_val <- tryCatch(logdensity(domain[2]), error = function(e) NA, warning = function(w) NA)

  if (is.na(lb_val) || is.infinite(lb_val)) {
    stop("logdensity must return a finite real value at the lower domain boundary.")
  }
  if (is.na(ub_val) || is.infinite(ub_val)) {
    stop("logdensity must return a finite real value at the upper domain boundary.")
  }

  if (!is.null(init_points)) {
    if (!is.numeric(init_points) || length(init_points) < 3) {
      stop("If provided, 'init_points' must be a numeric vector of at least 3 points within the domain.")
    }
    if (any(init_points <= domain[1]) || any(init_points >= domain[2])) {
      stop("All 'init_points' must lie strictly within the open domain interval.")
    }
    if (any(!is.finite(init_points))) {
      stop("'init_points' must contain only finite values.")
    }
    x <- sort(init_points)
  } else {
    # Choose initial points spread across the domain
    x <- seq(domain[1] + (domain[2] - domain[1]) / 5,
             domain[2] - (domain[2] - domain[1]) / 5,
             length.out = 5)
  }

  # Evaluate log-density at abscissae
  lx <- logdensity(x)
  if (any(!is.finite(lx))) {
    stop("logdensity returned non-finite values at initial points. Check your density function.")
  }

  # Validate log-concavity at initialization
  second_diffs <- .compute_second_differences(x, lx)
  if (any(second_diffs > 0)) {
    stop("The log-density is not log-concave at the initial points. ARS requires a log-concave log-density.")
  }

  # -------------------------------------------------------------------------
  # Build initial state
  # -------------------------------------------------------------------------
  state <- .build_state(x, lx, domain)

  # Storage for sampled values
  samples <- numeric(n)

  # Point pool (all abscissae ever evaluated)
  pool_x <- x
  pool_lx <- lx

  # -------------------------------------------------------------------------
  # Main sampling loop
  # -------------------------------------------------------------------------
  for (i in seq_len(n)) {
    # Rebuild envelope from current pool
    state <- .rebuild_envelope(pool_x, pool_lx, domain)

    if (verbose) {
      cat(sprintf("[Sample %d/%d] Envelope rebuilt with %d points.\n", i, n, length(pool_x)))
    }

    accepted <- FALSE
    reject_iter <- 0

    while (!accepted && reject_iter < max_iter) {
      reject_iter <- reject_iter + 1

      # Sample candidate from the lower envelope
      candidate <- .sample_from_lower(state, domain)

      # Evaluate log-density at candidate
      f_val <- logdensity(candidate)

      if (!is.finite(f_val)) {
        next
      }

      # Log-concavity guard
      concavity_ok <- .check_log_concavity(pool_x, pool_lx, candidate, f_val)

      if (!concavity_ok) {
        if (length(pool_x) >= max_iter * 2) {
          stop("Log-concavity violation detected. The log-density is not log-concave over the domain.")
        }
        # Add point and rebuild
        pool_x <- c(pool_x, candidate)
        pool_lx <- c(pool_lx, f_val)
        idx <- order(pool_x)
        pool_x <- pool_x[idx]
        pool_lx <- pool_lx[idx]
        if (verbose) {
          cat(sprintf("[Sample %d] Log-concavity violated at %.6f; added evaluation point.\n", i, candidate))
        }
        break  # restart the while loop
      }

      # Acceptance test: u < exp(f(u) - lower_envelope(u))
      lower_val <- .lower_envelope_at(candidate, state)
      u <- runif(1)
      log_u <- log(u)

      if (log_u < f_val - lower_val) {
        samples[i] <- candidate
        accepted <- TRUE
      } else {
        # Rejected — add the point and continue
        pool_x <- c(pool_x, candidate)
        pool_lx <- c(pool_lx, f_val)
        idx <- order(pool_x)
        pool_x <- pool_x[idx]
        pool_lx <- pool_lx[idx]
      }
    }

    if (!accepted) {
      stop("Failed to accept a sample within the maximum number of iterations.")
    }
  }

  structure(
    samples = samples,
    evaluation_points = unique(pool_x),
    class = "ars_result"
  )
}

# ============================================================================
# MODULAR AUXILIARY FUNCTIONS
# ============================================================================

#' Build initial state from abscissae and log-density values
.build_state <- function(x, lx, domain) {
  list(
    x = x,
    lx = lx,
    domain = domain,
    slopes = diff(lx) / diff(x),
    upper_a = numeric(length(x)),
    upper_b = numeric(length(x)),
    lower_a = numeric(length(x) - 1),
    lower_b = numeric(length(x) - 1),
    lower_w = diff(x)
  )
}

#' Rebuild the upper and lower envelopes from a set of abscissae
.rebuild_envelope <- function(x, lx, domain) {
  n <- length(x)
  state <- .build_state(x, lx, domain)
  s <- diff(lx) / diff(x)

  # Lower envelope (secants)
  for (j in seq_len(n - 1)) {
    state$lower_a[j] <- lx[j] - s[j] * x[j]
    state$lower_b[j] <- s[j]
  }

  # Upper envelope (tangents)
  for (j in seq_len(n)) {
    if (j == 1) {
      m <- s[1]
    } else if (j == n) {
      m <- s[n - 1]
    } else {
      m <- (s[j - 1] + s[j]) / 2
    }
    state$upper_a[j] <- lx[j] - m * x[j]
    state$upper_b[j] <- m
  }

  state
}

#' Evaluate the lower envelope at a point
.lower_envelope_at <- function(u, state) {
  x <- state$x
  n <- length(x)
  if (u <= x[1] | u >= x[n]) return(-Inf)
  j <- findInterval(u, x)
  if (j < 1 || j >= n) return(-Inf)
  state$lower_a[j] + state$lower_b[j] * u
}

#' Sample a candidate from under the lower envelope
.sample_from_lower <- function(state, domain) {
  x <- state$x
  n <- length(x)
  la <- state$lower_a
  lb <- state$lower_b

  # Cumulative area under each trapezoid
  areas <- numeric(n - 1)
  for (j in seq_len(n - 1)) {
    h1 <- la[j] + lb[j] * x[j]
    h2 <- la[j] + lb[j] * x[j + 1]
    areas[j] <- 0.5 * (h1 + h2) * (x[j + 1] - x[j])
  }

  total_area <- sum(areas)
  if (total_area <= 0) {
    return(runif(1, domain[1], domain[2]))
  }

  u <- runif(1) * total_area
  cum_area <- 0

  for (j in seq_len(n - 1)) {
    cum_area <- cum_area + areas[j]
    if (u <= cum_area) {
      target <- u - (cum_area - areas[j])
      h1 <- la[j] + lb[j] * x[j]
      h2 <- la[j] + lb[j] * x[j + 1]
      candidate <- .sample_trapezoid(target, h1, h2, x[j], x[j + 1])
      return(candidate)
    }
  }

  return(runif(1, domain[1], domain[2]))
}

#' Sample from a trapezoid with heights h1, h2 on [a, b]
.sample_trapezoid <- function(target, h1, h2, a, b) {
  area <- 0.5 * (h1 + h2) * (b - a)
  if (area <= 0) return((a + b) / 2)

  u <- runif(1) * area
  mid <- h1 * (b - a)

  if (u <= mid) {
    if (h1 > 0) {
      return(a + sqrt(2 * u * (b - a) / h1))
    } else {
      return(a + u / (0.5 * h2 * (b - a)) * (b - a))
    }
  } else {
    rem <- u - mid
    if (h2 > 0) {
      return(b - sqrt(2 * (area - rem) * (b - a) / h2))
    } else {
      return(a + rem / (0.5 * h1 * (b - a)) * (b - a))
    }
  }
}

#' Check log-concavity after adding a new point
.check_log_concavity <- function(pool_x, pool_lx, new_x, new_lx) {
  new_pool_x <- c(pool_x, new_x)
  new_pool_lx <- c(pool_lx, new_lx)
  idx <- order(new_pool_x)
  new_pool_x <- new_pool_x[idx]
  new_pool_lx <- new_pool_lx[idx]

  second_diffs <- .compute_second_differences(new_pool_x, new_pool_lx)
  all(second_diffs <= 0)
}

#' Compute second differences of log-density values
.compute_second_differences <- function(x, lx) {
  if (length(x) < 3) return(numeric(0))
  dx1 <- diff(x)
  dx2 <- diff(x[-1])
  slopes <- diff(lx) / c(dx1, dx2)
  diff(slopes) / 0.5 * (dx1[-length(dx1)] + dx2[-length(dx2)])
}

#' Print method for ars_result objects
print.ars_result <- function(x, ...) {
  cat("Adaptive Rejection Sampling Result\n")
  cat("===================================\n")
  cat(sprintf("Number of samples: %d\n", length(x$samples)))
  cat(sprintf("Mean: %.6f\n", mean(x$samples)))
  cat(sprintf("SD:   %.6f\n", sd(x$samples)))
  cat(sprintf("Evaluation points used: %d\n", length(x$evaluation_points)))
  cat("\nFirst 10 samples:\n")
  print(head(x$samples, 10))
}

# ============================================================================
# TEST FUNCTION
# ============================================================================

test <- function() {
  cat("============================================================\n")
  cat("Adaptive Rejection Sampling — Formal Test Suite\n")
  cat("============================================================\n\n")

  passed <- 0
  failed <- 0

  # --------------------------------------------------------------------------
  # Helper: report
  # --------------------------------------------------------------------------
  report <- function(name, result, details = "") {
    if (result) {
      cat(sprintf("%s: PASS", name))
      if (details != "") cat(sprintf("  (%s)", details))
      cat("\n")
      passed <<- passed + 1
    } else {
      cat(sprintf("%s: FAIL", name))
      if (details != "") cat(sprintf("  (%s)", details))
      cat("\n")
      failed <<- failed + 1
    }
  }

  # --------------------------------------------------------------------------
  # Helper: sample quality checks
  # --------------------------------------------------------------------------
  check_samples <- function(samples, expected_mean, expected_sd, tol_mean, tol_sd) {
    m <- mean(samples)
    s <- sd(samples)
    list(
      mean_ok = abs(m - expected_mean) < tol_mean,
      sd_ok = abs(s - expected_sd) < tol_sd,
      mean = m,
      sd = s
    )
  }

  # =========================================================================
  # TEST 1: Input validation — negative n
  # =========================================================================
  cat("[TEST 1] Input validation: negative n\n")
  tryCatch({
    ars(function(x) x, -1, domain = c(-10, 10))
    report("NEGATIVE_N", FALSE, "Should have thrown an error")
  }, error = function(e) {
    report("NEGATIVE_N", grepl("positive integer", e$message, ignore.case = TRUE))
  })

  # =========================================================================
  # TEST 2: Input validation — non-function logdensity
  # =========================================================================
  cat("[TEST 2] Input validation: non-function logdensity\n")
  tryCatch({
    ars(42, n = 10, domain = c(-10, 10))
    report("NON_FUNCTION_LOGDENSITY", FALSE, "Should have thrown an error")
  }, error = function(e) {
    report("NON_FUNCTION_LOGDENSITY", grepl("must be a function", e$message, ignore.case = TRUE))
  })

  # =========================================================================
  # TEST 3: Input validation — invalid domain
  # =========================================================================
  cat("[TEST 3] Input validation: invalid domain\n")
  tryCatch({
    ars(function(x) x, n = 10, domain = c(5, 2))
    report("INVALID_DOMAIN", FALSE, "Should have thrown an error")
  }, error = function(e) {
    report("INVALID_DOMAIN", grepl("finite interval", e$message, ignore.case = TRUE))
  })

  # =========================================================================
  # TEST 4: Input validation — non-log-concave density
  # =========================================================================
  cat("[TEST 4] Input validation: non-log-concave density\n")
  bimodal_logdensity <- function(x) {
    log(0.5 * dnorm(x, mean = -3, sd = 0.5, log = TRUE) +
         0.5 * dnorm(x, mean = 3, sd = 0.5, log = TRUE))
  }
  tryCatch({
    ars(bimodal_logdensity, n = 10, domain = c(-6, 6))
    report("NON_LOGCONCAVE", FALSE, "Should have thrown an error")
  }, error = function(e) {
    report("NON_LOGCONCAVE", grepl("log-concave", e$message, ignore.case = TRUE))
  })

  # =========================================================================
  # TEST 5: Standard normal distribution
  # =========================================================================
  cat("[TEST 5] Sampling from standard normal\n")
  dnorm_log <- function(x) dnorm(x, mean = 0, sd = 1, log = TRUE)
  normal_result <- tryCatch({
    ars(dnorm_log, n = 5000, domain = c(-5, 5), verbose = FALSE)
  }, error = function(e) {
    cat(sprintf("  Error: %s\n", e$message))
    NULL
  })

  if (!is.null(normal_result)) {
    stats <- check_samples(normal_result$samples, 0, 1, 0.1, 0.15)
    report("NORMAL_MEAN", stats$mean_ok,
           sprintf("mean=%.4f (expected 0)", stats$mean))
    report("NORMAL_SD", stats$sd_ok,
           sprintf("sd=%.4f (expected 1)", stats$sd))

    ks_result <- ks.test(normal_result$samples, "pnorm")
    report("NORMAL_KS", ks_result$p.value > 0.01,
           sprintf("KS p-value=%.4f", ks_result$p.value))

    write.table(normal_result$samples, file = "/app/normal_samples.txt",
                row.names = FALSE, col.names = FALSE)
    cat("  Samples saved to /app/normal_samples.txt\n")
  } else {
    report("NORMAL_MEAN", FALSE, "Sampling failed")
    report("NORMAL_SD", FALSE, "Sampling failed")
    report("NORMAL_KS", FALSE, "Sampling failed")
  }

  # =========================================================================
  # TEST 6: Exponential distribution
  # =========================================================================
  cat("[TEST 6] Sampling from exponential(1)\n")
  dexp_log <- function(x) dexp(x, rate = 1, log = TRUE)
  exp_result <- tryCatch({
    ars(dexp_log, n = 5000, domain = c(0, 10), verbose = FALSE)
  }, error = function(e) {
    cat(sprintf("  Error: %s\n", e$message))
    NULL
  })

  if (!is.null(exp_result)) {
    stats <- check_samples(exp_result$samples, 1, 1, 0.1, 0.15)
    report("EXPONENTIAL_MEAN", stats$mean_ok,
           sprintf("mean=%.4f (expected 1)", stats$mean))
    report("EXPONENTIAL_SD", stats$sd_ok,
           sprintf("sd=%.4f (expected 1)", stats$sd))

    ks_result <- ks.test(exp_result$samples, "pexp", rate = 1)
    report("EXPONENTIAL_KS", ks_result$p.value > 0.01,
           sprintf("KS p-value=%.4f", ks_result$p.value))

    write.table(exp_result$samples, file = "/app/exponential_samples.txt",
                row.names = FALSE, col.names = FALSE)
    cat("  Samples saved to /app/exponential_samples.txt\n")
  } else {
    report("EXPONENTIAL_MEAN", FALSE, "Sampling failed")
    report("EXPONENTIAL_SD", FALSE, "Sampling failed")
    report("EXPONENTIAL_KS", FALSE, "Sampling failed")
  }

  # =========================================================================
  # TEST 7: Gamma distribution (shape=3, rate=1) — log-concave
  # =========================================================================
  cat("[TEST 7] Sampling from Gamma(3, 1)\n")
  dgamma_log <- function(x) dgamma(x, shape = 3, rate = 1, log = TRUE)
  gamma_result <- tryCatch({
    ars(dgamma_log, n = 5000, domain = c(0.01, 15), verbose = FALSE)
  }, error = function(e) {
    cat(sprintf("  Error: %s\n", e$message))
    NULL
  })

  if (!is.null(gamma_result)) {
    stats <- check_samples(gamma_result$samples, 3, sqrt(3), 0.15, 0.2)
    report("GAMMA_MEAN", stats$mean_ok,
           sprintf("mean=%.4f (expected 3)", stats$mean))
    report("GAMMA_SD", stats$sd_ok,
           sprintf("sd=%.4f (expected %.4f)", stats$sd, sqrt(3)))

    ks_result <- ks.test(gamma_result$samples, "pgamma", shape = 3, rate = 1)
    report("GAMMA_KS", ks_result$p.value > 0.01,
           sprintf("KS p-value=%.4f", ks_result$p.value))
  } else {
    report("GAMMA_MEAN", FALSE, "Sampling failed")
    report("GAMMA_SD", FALSE, "Sampling failed")
    report("GAMMA_KS", FALSE, "Sampling failed")
  }

  # =========================================================================
  # TEST 8: Beta distribution (shape1=2, shape2=5) — log-concave on (0,1)
  # =========================================================================
  cat("[TEST 8] Sampling from Beta(2, 5)\n")
  dbeta_log <- function(x) dbeta(x, shape1 = 2, shape2 = 5, log = TRUE)
  beta_result <- tryCatch({
    ars(dbeta_log, n = 5000, domain = c(0.001, 0.999), verbose = FALSE)
  }, error = function(e) {
    cat(sprintf("  Error: %s\n", e$message))
    NULL
  })

  if (!is.null(beta_result)) {
    expected_mean <- 2 / 7
    expected_sd <- sqrt(2 * 5 / ((2 + 5)^2 * (2 + 5 + 1)))
    stats <- check_samples(beta_result$samples, expected_mean, expected_sd, 0.05, 0.05)
    report("BETA_MEAN", stats$mean_ok,
           sprintf("mean=%.4f (expected %.4f)", stats$mean, expected_mean))
    report("BETA_SD", stats$sd_ok,
           sprintf("sd=%.4f (expected %.4f)", stats$sd, expected_sd))

    ks_result <- ks.test(beta_result$samples, "pbeta", shape1 = 2, shape2 = 5)
    report("BETA_KS", ks_result$p.value > 0.01,
           sprintf("KS p-value=%.4f", ks_result$p.value))
  } else {
    report("BETA_MEAN", FALSE, "Sampling failed")
    report("BETA_SD", FALSE, "Sampling failed")
    report("BETA_KS", FALSE, "Sampling failed")
  }

  # =========================================================================
  # TEST 9: Custom log-concave density (truncated normal)
  # =========================================================================
  cat("[TEST 9] Sampling from truncated normal N(2, 1) on [0, 5]\n")
  dtrunc_normal_log <- function(x) {
    log(dnorm(x, mean = 2, sd = 1) / (pnorm(5, mean = 2, sd = 1) - pnorm(0, mean = 2, sd = 1)))
  }
  trunc_result <- tryCatch({
    ars(dtrunc_normal_log, n = 5000, domain = c(0, 5), verbose = FALSE)
  }, error = function(e) {
    cat(sprintf("  Error: %s\n", e$message))
    NULL
  })

  if (!is.null(trunc_result)) {
    stats <- check_samples(trunc_result$samples, 2, 0.85, 0.1, 0.1)
    report("TRUNC_NORMAL_MEAN", stats$mean_ok,
           sprintf("mean=%.4f (expected 2)", stats$mean))
    report("TRUNC_NORMAL_SD", stats$sd_ok,
           sprintf("sd=%.4f (expected ~0.85)", stats$sd))
  } else {
    report("TRUNC_NORMAL_MEAN", FALSE, "Sampling failed")
    report("TRUNC_NORMAL_SD", FALSE, "Sampling failed")
  }

  # =========================================================================
  # Summary
  # =========================================================================
  cat("\n============================================================\n")
  cat(sprintf("Results: %d passed, %d failed\n", passed, failed))
  cat("============================================================\n")

  if (failed > 0) {
    cat("\nSome tests FAILED. Review the output above.\n")
  } else {
    cat("\nAll tests PASSED.\n")
  }

  invisible(list(passed = passed, failed = failed))
}
